//! Themes, named people/organisations/places and events used by the analysis.
//! Hand-made lists: transparent, editable and easy to check against the texts.

pub struct Theme {
    pub slug: &'static str,
    pub name: &'static str,
    pub description: &'static str,
    /// terms that place a message in the theme
    pub terms: &'static [&'static str],
    /// common words that count only when a message also has one of the terms above
    pub weak: &'static [&'static str],
    /// set phrases that contain a term but mean something else ("tanah air", "siaran pers");
    /// they are matched and then ignored
    pub stops: &'static [&'static str],
    /// words that turn weak words into evidence: a message with weak words and these words
    /// together, in the same paragraph and three hits in all, joins the theme even without one
    /// of its terms ("Ambon" with "kerusuhan" and "pengungsi")
    pub context: &'static [&'static str],
}

/// A message joins a theme when it has at least one of the theme's terms and two hits in
/// all (terms and weak words), or one term in its title, or (for themes with context words)
