/// Whether a theme can apply to a message of this date: the May 1998 riots cannot be the
/// subject of a message written before they began (a call for a "20 May" uprising in April).
pub fn theme_possible(slug: &str, date: Option<&str>) -> bool {
    slug != "may-1998" || date.map(|d| d >= "1998-05-13").unwrap_or(false)
}

pub struct Entity {
    pub slug: &'static str,
    pub name: &'static str,
    pub kind: &'static str,
    pub aliases: &'static [&'static str],
}

