/// Names that are also common words: they count only when written with a capital letter.
pub static CASE_SENSITIVE: &[&str] = &["medan", "munir", "theys", "kwik", "tutut"];

macro_rules! e {
    ($slug:expr, $name:expr, $kind:expr, [$($a:expr),*]) => { Entity { slug: $slug, name: $name, kind: $kind, aliases: &[$($a),*] } };
}

